/* app/scale-v3.css */
/* Do grão ao planeta: rabiscos simples */

.scale-doodle{max-width:1160px;margin:auto;padding:62px 20px 100px}
.scale-doodle-card{background:#c9f06a;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3.5vw,40px)}
.scale-doodle-head{display:flex;align-items:flex-start;justify-content:space-between;gap:22px}
.scale-doodle-head>div:first-child>span{font-size:10px;font-weight:900;letter-spacing:.12em}
.scale-doodle-head h2{font-size:clamp(40px,6vw,72px);line-height:.9;letter-spacing:-.06em;margin:7px 0 0}
.scale-doodle-head h2 em{font-family:var(--serif);font-weight:400}
.scale-doodle-ratio{background:#fffdf8;border:2px solid #111;border-radius:12px;padding:8px 11px;text-align:right;transform:rotate(1deg)}
.scale-doodle-ratio b{display:block;font-size:clamp(27px,3.5vw,40px);line-height:1}
.scale-doodle-ratio span{display:block;font-size:8px;font-weight:900;text-transform:uppercase;letter-spacing:.08em;margin-top:3px}

.doodle-paper{height:525px;position:relative;margin-top:22px;background:#fffdf8;border:2px solid #111;border-radius:12px;overflow:hidden}
.doodle-floor{position:absolute;left:4%;right:3%;bottom:8%;width:93%;height:54px;color:#111}
.doodle-object{position:absolute;bottom:14%;display:flex;align-items:flex-end;justify-content:center;color:#111;transform:translateX(-50%);transform-origin:50% 100%;animation:doodle-in .2s ease-out}
.doodle-object svg{height:100%;width:auto;display:block;overflow:visible}
.doodle-object.previous{left:31%;color:#8757f2}
.doodle-object.current{left:70%;color:#111}
.doodle-echo{opacity:.2}
.doodle-label{position:absolute;left:50%;bottom:-31px;transform:translateX(-50%) rotate(-1deg);white-space:nowrap;font-size:10px;background:#fffdf8;border:1.5px solid #111;padding:3px 6px}
.doodle-label strong{font-size:9px}.doodle-label span{font-family:var(--serif);font-size:9px;margin-left:5px}

.doodle-measure{position:absolute;right:6%;top:15%;bottom:14%;width:48px;display:flex;align-items:center;justify-content:center}
.doodle-measure svg{position:absolute;inset:0;width:100%;height:100%;color:#111}
.doodle-measure span{position:relative;background:#fffdf8;padding:2px 4px;font-size:9px;font-weight:900;transform:rotate(-2deg)}

.doodle-note{position:absolute;left:7%;top:7%;width:92px;background:#fff9a8;border:1.5px solid #111;padding:6px;text-align:center;transform:rotate(-2deg);box-shadow:2px 3px 0 rgba(17,17,17,.18)}
.doodle-note>span{font-size:7px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}
.doodle-note>div{height:50px;display:grid;place-items:center;color:#8757f2}.doodle-note svg{max-width:46px;max-height:46px}.doodle-note small{font-size:7px;font-weight:900}

.scale-doodle-sentence{font-family:var(--serif);font-size:clamp(18px,2vw,23px);max-width:760px;margin:15px 0 20px}
.scale-doodle-controls{display:grid;grid-template-columns:auto minmax(90px,1fr) auto;align-items:center;gap:14px;border-top:2px solid #111;padding-top:14px}
.scale-doodle-controls button{border:2px solid #111;background:#fffdf8;border-radius:999px;padding:9px 13px;font-weight:900;cursor:pointer;box-shadow:0 3px 0 #111}
.scale-doodle-controls button.primary{background:#111;color:#fffdf8}.scale-doodle-controls button:disabled{opacity:.3;box-shadow:none}
.scale-doodle-progress{height:7px;border:2px solid #111;background:#fffdf8;border-radius:999px;overflow:hidden}.scale-doodle-progress i{display:block;height:100%;background:#111;transition:width .2s ease}
.scale-doodle-hint{text-align:center;font-size:7px;font-weight:900;text-transform:uppercase;letter-spacing:.1em;margin:9px 0 0;opacity:.55}

.scale-doodle-nav{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:25px}
.scale-doodle-nav button{border:2px solid #111;border-radius:12px;background:#fffdf8;padding:9px;text-align:left;cursor:pointer;display:grid;grid-template-columns:auto 1fr;gap:2px 7px;align-items:baseline}
.scale-doodle-nav button.active{background:#c9f06a;box-shadow:0 3px 0 #111;transform:rotate(-.5deg)}
.scale-doodle-nav span{font-size:8px;font-weight:900;color:#777}.scale-doodle-nav strong{font-size:11px}.scale-doodle-nav small{grid-column:2;font-family:var(--serif);font-size:10px}

@keyframes doodle-in{from{opacity:0;transform:translateX(-50%) translateY(5px) rotate(-.8deg)}to{opacity:1;transform:translateX(-50%) translateY(0) rotate(0)}}

@media(max-width:760px){
  .scale-doodle{padding:42px 10px 72px}
  .scale-doodle-card{padding:13px 9px 12px;border-width:2px;border-radius:16px;box-shadow:0 4px 0 #111}
  .scale-doodle-head{display:block}.scale-doodle-head h2{font-size:clamp(35px,11vw,47px)}
  .scale-doodle-ratio{display:flex;align-items:center;justify-content:space-between;text-align:left;margin-top:10px;padding:7px 9px}.scale-doodle-ratio b{font-size:25px}.scale-doodle-ratio span{margin:0}
  .doodle-paper{height:380px;margin-top:13px}
  .doodle-floor{bottom:8%;height:44px}.doodle-object{bottom:15%}.doodle-object.previous{left:29%}.doodle-object.current{left:69%}
  .doodle-label{bottom:-26px;padding:2px 4px}.doodle-label strong,.doodle-label span{font-size:7px}
  .doodle-measure{right:1%;top:19%;bottom:15%;width:36px}.doodle-measure span{font-size:7px}
  .doodle-note{left:4%;top:4%;width:72px;padding:4px}.doodle-note>div{height:39px}.doodle-note svg{max-width:36px;max-height:36px}.doodle-note small{font-size:6px}
  .scale-doodle-sentence{font-size:17px;margin:12px 1px 16px}
  .scale-doodle-controls{gap:7px}.scale-doodle-controls button{font-size:10px;padding:8px 9px}
  .scale-doodle-nav{display:flex;overflow-x:auto;gap:6px;margin-top:21px;padding-bottom:8px;scrollbar-width:none}.scale-doodle-nav::-webkit-scrollbar{display:none}.scale-doodle-nav button{min-width:116px}
}

@media(max-width:390px){
  .doodle-paper{height:340px}.scale-doodle-head h2{font-size:34px}.scale-doodle-controls button{padding:8px 7px;font-size:9px}
}

@media(prefers-reduced-motion:reduce){
  .doodle-object{animation:none}.scale-doodle-progress i{transition:none}
}


