/* ENTRE: curadoria em camadas */
.collection-block{padding:0 0 105px}
.collection-heading{max-width:820px;margin:0 0 30px;padding-top:26px;border-top:2px solid #111}
.collection-heading>span{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.12em}
.collection-heading h2{font-family:var(--serif);font-weight:400;font-size:clamp(34px,5vw,58px);line-height:1.02;letter-spacing:-.04em;margin:9px 0 10px}
.collection-heading p{color:#555;max-width:680px;margin:0;font-size:15px}
.collection-secondary{padding-top:20px}
.collection-new{padding-top:20px}
.experimental-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.compact-tile{min-height:390px;padding:13px;box-shadow:0 5px 0 #111}
.compact-tile .tile-visual{min-height:185px;padding:8px}
.compact-tile .tile-copy h2{font-size:clamp(28px,3vw,39px)}
.compact-tile .tile-copy p{font-size:14px}

/* novos tons */
.tile-mint{background:#b9e4c8}.tone-mint{--accent:#b9e4c8}
.tile-coral{background:#ffb38d}.tone-coral{--accent:#ffb38d}
.tile-lilac{background:#cfc7ff}.tone-lilac{--accent:#cfc7ff}
.tile-ice{background:#bfe9f5}.tone-ice{--accent:#bfe9f5}
.tile-sand{background:#e7d39b}.tone-sand{--accent:#e7d39b}
.tile-gold{background:#ffd870}.tone-gold{--accent:#ffd870}
.tile-plum{background:#d7b7ef}.tone-plum{--accent:#d7b7ef}

/* mente: Ebbinghaus estável em SVG */
.ebbinghaus-svg-wrap{width:min(760px,100%);margin:0 auto 8px}
.ebbinghaus-svg{width:100%;height:auto;overflow:visible}
.ebbinghaus-svg .eb-surround circle{fill:#fff;stroke:#111;stroke-width:3;transition:r .12s linear,cx .12s linear,cy .12s linear}
.ebbinghaus-svg .eb-center{fill:#111}
.ebbinghaus-svg text{font-size:17px;font-weight:900;text-anchor:middle;fill:#111}
.ebbinghaus-svg .eb-guide{stroke:#ff4e7a;stroke-width:2;stroke-dasharray:7 6;opacity:.8}
.ebbinghaus-svg-wrap.revealed .eb-center{stroke:#ff4e7a;stroke-width:5}
.illusion-context label{align-items:center}.illusion-context label b{font-family:var(--serif);font-size:12px;text-transform:none;letter-spacing:0}

/* 09 rede */
.spread-lab,.cooperate-lab,.center-lab,.memory-lab,.attention-lab,.evidence-lab,.change-lab{max-width:1160px;margin:auto;padding:70px 20px 105px}
.spread-card{background:#b9e4c8;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3vw,36px)}
.spread-head,.change-head,.memory-head,.center-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}
.spread-head>div:first-child>span,.change-head>div:first-child>span,.memory-head>div:first-child>span,.center-head>div:first-child>span{font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.11em}
.spread-head h2,.change-head h2,.memory-head h2,.center-head h2{font-size:clamp(40px,5.5vw,68px);line-height:.92;letter-spacing:-.055em;margin:6px 0 0}
.spread-counter{background:#fffdf8;border:2px solid #111;border-radius:13px;padding:9px 12px;text-align:right;transform:rotate(1deg)}.spread-counter strong{display:block;font-size:34px;line-height:1}.spread-counter span{font-size:8px;font-weight:900;text-transform:uppercase}
.spread-board{position:relative;margin-top:22px;background:#fffdf8;border:2px solid #111;border-radius:14px;overflow:hidden}.spread-board svg{width:100%;display:block}
.spread-lines line{stroke:#111;stroke-width:3;opacity:.22}.spread-lines .bridge{stroke-width:6;stroke-dasharray:9 6;opacity:.68}
.spread-people g{cursor:pointer}.spread-people .person-ring{fill:#fffdf8;stroke:#111;stroke-width:3;transition:fill .2s}.spread-people .person-core{fill:#111}.spread-people g.active .person-ring{fill:#7956d8}.spread-people g.active .person-core{fill:#fff}.spread-people .seed-mark{fill:none!important;stroke:#111;stroke-width:2;stroke-dasharray:5 4}
.spread-labels{position:absolute;left:12px;right:12px;top:10px;display:flex;justify-content:space-between;pointer-events:none}.spread-labels span{background:#fffdf8;padding:2px 4px;font-size:8px;font-weight:900;text-transform:uppercase}
.spread-controls{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:end;margin-top:16px}.seed-readout{display:flex;align-items:baseline;gap:8px}.seed-readout span{font-size:8px;font-weight:900;text-transform:uppercase}.seed-readout strong{font-size:24px}.seed-readout small{font-family:var(--serif)}
.bridge-button,.spread-run{border:2px solid #111;border-radius:13px;background:#fffdf8;padding:9px 11px;font-weight:900;cursor:pointer}.bridge-button{display:flex;align-items:center;gap:8px;text-align:left}.bridge-button i{width:10px;height:10px;border-radius:50%;background:#bbb}.bridge-button.on{background:#fff5a8}.bridge-button.on i{background:#111}.bridge-button span{display:flex;flex-direction:column}.bridge-button small{font-family:var(--serif);font-size:9px}.spread-run{border-radius:999px;background:#111;color:#fffdf8;padding:11px 16px}.spread-run:disabled{opacity:.35}
.spread-result{margin-top:17px;background:#fffdf8;border:2px solid #111;border-radius:13px;padding:14px 16px}.spread-result strong{font-size:22px}.spread-result p{font-family:var(--serif);font-size:17px;margin:5px 0 10px}.spread-result button{border:0;border-bottom:2px solid #111;background:transparent;font-weight:900;cursor:pointer}
.spread-thought,.center-thought,.memory-thought,.attention-thought,.evidence-thought,.change-thought{font-family:var(--serif);font-size:clamp(30px,4.8vw,56px);line-height:1.04;max-width:930px;text-align:center;margin:74px auto 0}

/* 10 cooperação */
.cooperate-card,.cooperate-finale{background:#ffb38d;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(20px,4vw,46px)}
.cooperate-card>header{display:flex;justify-content:space-between;gap:20px}.cooperate-card>header span{font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.1em}.cooperate-card h2{font-size:clamp(44px,6vw,76px);line-height:.9;margin:5px 0 0;letter-spacing:-.06em}
.score-pair{display:flex;gap:8px}.score-pair span{background:#fffdf8;border:2px solid #111;border-radius:12px;padding:8px 10px;display:flex;flex-direction:column}.score-pair b{font-size:25px}
.payoff-note{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0}.payoff-note span{background:rgba(255,253,248,.72);border:1.5px solid #111;border-radius:10px;padding:7px;font-size:10px}.payoff-note b{display:block;font-size:13px}
.round-track{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.round-track>div{min-height:92px;border:2px solid #111;border-radius:12px;background:#fffdf8;padding:8px;display:flex;flex-direction:column;opacity:.45}.round-track>div.played{opacity:1}.round-track span{font-size:8px;font-weight:900}.round-track strong{margin-top:auto}.round-track small{font-family:var(--serif)}
.cooperate-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.cooperate-actions button{min-height:130px;border:3px solid #111;border-radius:16px;cursor:pointer;text-align:left;padding:16px}.cooperate-actions .share{background:#fffdf8}.cooperate-actions .keep{background:#111;color:#fffdf8}.cooperate-actions span{font-size:9px;font-weight:900;text-transform:uppercase}.cooperate-actions strong{display:block;font-size:34px;margin-top:12px}
.opponent-reveal{margin-top:18px;background:#fffdf8;border:2px solid #111;border-radius:13px;padding:15px}.opponent-reveal>span{font-size:8px;font-weight:900;text-transform:uppercase}.opponent-reveal h3{font-size:36px;margin:4px 0}.opponent-reveal p{font-family:var(--serif)}.opponent-reveal button,.cooperate-finale button{border:2px solid #111;border-radius:999px;background:#111;color:#fffdf8;padding:9px 13px;font-weight:900;cursor:pointer}
.cooperate-finale{text-align:center}.cooperate-finale>span{font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.11em}.cooperate-finale h2{font-family:var(--serif);font-size:clamp(42px,6vw,72px);font-weight:400;line-height:1;margin:10px auto 20px;max-width:850px}.final-score{display:flex;justify-content:center;align-items:center;gap:10px}.final-score strong{font-size:54px}.final-score small{font-size:10px}.final-score i{width:1px;height:50px;background:#111;margin:0 12px}.opponent-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:28px 0}.opponent-summary article{background:#fffdf8;border:2px solid #111;border-radius:12px;padding:12px;text-align:left}.opponent-summary span{font-size:8px;font-weight:900;text-transform:uppercase}.opponent-summary strong{display:block;font-size:22px}.opponent-summary p{font-family:var(--serif);font-size:13px}

/* 11 memória */
.memory-card{background:#cfc7ff;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3vw,36px)}.memory-countdown{font-size:62px;line-height:1}
.memory-room{position:relative;margin-top:20px;display:grid;grid-template-columns:repeat(4,1fr);height:420px;background:#fffdf8;border:2px solid #111;border-radius:14px;overflow:hidden}.memory-cell{position:relative;border:0;border-right:1px dashed rgba(17,17,17,.16);border-bottom:1px dashed rgba(17,17,17,.16);background:transparent;display:grid;place-items:center}.memory-room.recall .memory-cell{cursor:pointer}.memory-room.recall .memory-cell:hover{background:rgba(121,86,216,.08)}
.memory-overlay{position:absolute;inset:0;z-index:5;background:rgba(255,253,248,.94);display:grid;place-items:center;align-content:center;gap:12px}.memory-overlay span{font-family:var(--serif);font-size:22px}.memory-overlay button,.memory-result button{border:2px solid #111;border-radius:999px;background:#111;color:#fffdf8;padding:9px 13px;font-weight:900;cursor:pointer}
.memory-shape{position:relative;display:block;width:58px;height:58px;color:#111}.memory-shape.book{border:4px solid currentColor;border-radius:3px;transform:rotate(-5deg)}.memory-shape.book i:first-child{position:absolute;left:10px;top:0;bottom:0;border-left:3px solid currentColor}.memory-shape.book i:last-child{position:absolute;left:20px;right:6px;top:13px;border-top:3px solid currentColor}
.memory-shape.mug{border:4px solid currentColor;border-radius:4px 4px 12px 12px;width:48px;height:48px}.memory-shape.mug:after{content:"";position:absolute;right:-18px;top:10px;width:16px;height:20px;border:4px solid currentColor;border-left:0;border-radius:0 14px 14px 0}
.memory-shape.plant:before{content:"";position:absolute;left:21px;bottom:0;width:22px;height:25px;border:4px solid currentColor;border-radius:3px 3px 12px 12px}.memory-shape.plant i{position:absolute;width:28px;height:16px;border:4px solid currentColor;border-radius:100% 0 100% 0}.memory-shape.plant i:nth-child(1){left:1px;top:8px;transform:rotate(20deg)}.memory-shape.plant i:nth-child(2){right:1px;top:4px;transform:scaleX(-1) rotate(20deg)}.memory-shape.plant i:nth-child(3){left:16px;top:22px}
.memory-shape.clock{border:4px solid currentColor;border-radius:50%}.memory-shape.clock i:first-child{position:absolute;left:27px;top:10px;height:19px;border-left:3px solid currentColor}.memory-shape.clock i:last-child{position:absolute;left:27px;top:27px;width:15px;border-top:3px solid currentColor;transform:rotate(28deg);transform-origin:left}
.memory-miss{position:absolute;opacity:.28;transform:scale(.72)}.memory-recall{display:flex;align-items:center;gap:12px;margin-top:15px;padding:12px 14px;background:#fffdf8;border:2px solid #111;border-radius:12px}.memory-recall>span{font-size:9px;font-weight:900}.memory-recall>div{display:flex;align-items:center;gap:8px}.memory-recall .memory-shape{width:36px;height:36px;transform:scale(.62);transform-origin:center}.memory-recall p{margin-left:auto;font-family:var(--serif)}
.memory-result{display:grid;grid-template-columns:auto 1fr auto;gap:14px;align-items:center;margin-top:15px;background:#fffdf8;border:2px solid #111;border-radius:12px;padding:13px}.memory-result>div{display:flex;flex-direction:column}.memory-result strong{font-size:34px}.memory-result p{font-family:var(--serif);margin:0}

/* 12 pequena mudança */
.change-card{background:#bfe9f5;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3vw,36px)}.change-meter{background:#fffdf8;border:2px solid #111;border-radius:12px;padding:8px 10px;text-align:right}.change-meter span{display:block;font-size:8px;font-weight:900;text-transform:uppercase}.change-meter strong{font-size:30px}
.change-stage{position:relative;margin-top:20px;background:#fffdf8;border:2px solid #111;border-radius:14px;overflow:hidden}.change-stage svg{display:block;width:100%}.change-grid{fill:none;stroke:#111;stroke-width:1;opacity:.09}.change-path{fill:none;stroke-width:5;stroke-linecap:round;stroke-linejoin:round}.change-path.one{stroke:#111}.change-path.two{stroke:#7a55d8;stroke-dasharray:9 6}.change-dot.one{fill:#111}.change-dot.two{fill:#7a55d8}.change-legend{position:absolute;left:12px;top:10px;display:flex;gap:10px;background:#fffdf8;padding:4px 6px;font-size:9px;font-weight:900}.change-legend span{display:flex;align-items:center;gap:5px}.change-legend i{width:12px;height:4px;background:#111}.change-legend i.two{background:#7a55d8}
.change-control{margin-top:16px;display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center}.change-control>div:first-child{display:flex;flex-direction:column}.change-control>div:first-child span{font-size:8px;font-weight:900;text-transform:uppercase}.change-control>div:first-child strong{font-family:var(--serif)}.change-control input{width:100%;accent-color:#111}.change-scale{grid-column:2;display:flex;justify-content:space-between;font-size:8px;font-weight:900;text-transform:uppercase}.change-control button{grid-column:3;grid-row:1/3;border:2px solid #111;border-radius:999px;background:#111;color:#fffdf8;padding:10px 13px;font-weight:900;cursor:pointer}.change-control button:disabled{opacity:.5}.change-result{margin-top:15px;padding:13px 15px;background:#fffdf8;border:2px solid #111;border-radius:12px}.change-result p{font-family:var(--serif);margin:4px 0}

/* 13 centro */
.center-card{background:#e7d39b;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3vw,36px)}.center-tag{background:#fffdf8;border:2px solid #111;border-radius:999px;padding:7px 9px;font-size:9px;font-weight:900;text-transform:uppercase}.center-map-wrap{position:relative;margin-top:18px}.center-map{width:100%;display:block;background:#fffdf8;border:2px solid #111;border-radius:14px;touch-action:none;cursor:crosshair}.center-street{fill:none;stroke:#111;stroke-width:18;opacity:.06;stroke-linecap:round}.resident circle{fill:#111}.resident path{fill:#fffdf8;stroke:#111;stroke-width:3}.walk-lines line{stroke:#7a55d8;stroke-width:2;stroke-dasharray:6 5;opacity:.55}.fountain text{font-size:10px;font-weight:900;text-anchor:middle;fill:#111}.your-fountain circle{fill:#111}.your-fountain path{stroke:#fffdf8;stroke-width:3}.best-fountain circle:first-child{fill:none;stroke:#7a55d8;stroke-width:4;stroke-dasharray:7 5}.best-fountain circle:nth-child(2){fill:#7a55d8}.center-overlay{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-1deg);background:#fff5a8;border:2px solid #111;border-radius:999px;padding:9px 12px;font-weight:900;pointer-events:none}
.center-criteria{margin-top:15px}.center-criteria>span{font-size:8px;font-weight:900;text-transform:uppercase}.center-criteria>div{display:flex;gap:7px;flex-wrap:wrap;margin-top:6px}.center-criteria button{border:2px solid #111;border-radius:999px;background:#fffdf8;padding:8px 10px;font-weight:900;cursor:pointer}.center-criteria button.active{background:#111;color:#fffdf8}.center-actions{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;margin-top:15px;padding-top:15px;border-top:2px solid #111}.center-actions>div{display:flex;flex-direction:column}.center-actions span{font-size:8px;font-weight:900;text-transform:uppercase}.center-actions strong{font-family:var(--serif)}.center-actions button{border:2px solid #111;border-radius:999px;background:#111;color:#fffdf8;padding:9px 12px;font-weight:900;cursor:pointer}.center-actions button:disabled{opacity:.35}.center-result{margin-top:14px;background:#fffdf8;border:2px solid #111;border-radius:12px;padding:13px}.center-result p{font-family:var(--serif);font-size:18px;margin:0 0 6px}

/* 14 atenção */
.attention-card{background:#ffd870;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3vw,36px)}.attention-card>header span{font-size:9px;font-weight:900;text-transform:uppercase}.attention-card>header h2{font-size:clamp(42px,6vw,70px);line-height:.9;margin:5px 0 18px;letter-spacing:-.06em}.attention-stage{height:360px;position:relative;background:#fffdf8;border:2px solid #111;border-radius:14px;overflow:hidden}.attention-line{position:absolute;left:50%;top:0;bottom:0;border-left:3px dashed rgba(17,17,17,.3)}.attention-token{position:absolute;top:48%;left:-40px;width:34px;height:34px;border-radius:50%;border:3px solid #111;animation:attention-cross .58s linear forwards}.attention-token.blue{background:#5aa8ff}.attention-token.pink{background:#ff86ae}.attention-token.reverse{left:auto;right:-40px;animation-name:attention-cross-reverse}.attention-stranger{position:absolute;inset:0;pointer-events:none}.attention-stranger span{position:absolute;top:18%;left:-90px;font-size:150px;line-height:1;color:#111;opacity:.85;animation:attention-stranger 2.45s linear forwards}.attention-overlay{position:absolute;inset:0;background:rgba(255,253,248,.94);display:grid;place-items:center}.attention-overlay button,.attention-question button,.attention-result button{border:2px solid #111;border-radius:999px;background:#111;color:#fffdf8;padding:9px 13px;font-weight:900;cursor:pointer}
@keyframes attention-cross{to{left:calc(100% + 40px);top:38%}}@keyframes attention-cross-reverse{to{right:calc(100% + 40px);top:61%}}@keyframes attention-stranger{to{left:calc(100% + 90px);transform:rotate(40deg)}}
.attention-question,.attention-result{margin-top:15px;background:#fffdf8;border:2px solid #111;border-radius:12px;padding:14px}.attention-question>span{font-size:8px;font-weight:900;text-transform:uppercase}.attention-question h3{font-family:var(--serif);font-size:28px;margin:4px 0 10px}.attention-question>div{display:flex;gap:7px;flex-wrap:wrap}.attention-question button{min-width:48px}.attention-result>div{display:flex;justify-content:space-between;gap:10px}.attention-result strong{font-size:22px}.attention-result span{font-family:var(--serif)}.attention-result p{font-family:var(--serif)}

/* 15 evidência */
.evidence-card{background:#d7b7ef;border:3px solid #111;border-radius:20px;box-shadow:0 7px 0 #111;padding:clamp(18px,3vw,36px)}.evidence-card>header{display:flex;justify-content:space-between;gap:20px}.evidence-card>header span{font-size:9px;font-weight:900;text-transform:uppercase}.evidence-card h2{font-size:clamp(42px,6vw,70px);line-height:.9;margin:5px 0 0;letter-spacing:-.06em}.evidence-card>header>strong{font-size:15px}
.jar-row{display:grid;grid-template-columns:210px 1fr 210px;gap:18px;align-items:center;margin-top:20px}.jar{background:#fffdf8;border:2px solid #111;border-radius:14px;padding:12px}.jar>span{font-size:9px;font-weight:900;text-transform:uppercase}.jar>div{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:10px 0}.jar i,.evidence-stream i{display:block;aspect-ratio:1;border-radius:50%;border:2px solid #111}.jar i.purple,.evidence-stream i.purple{background:#8157da}.jar i.green,.evidence-stream i.green{background:#8dd469}.jar small{font-family:var(--serif)}.evidence-stream{min-height:72px;display:flex;align-items:center;justify-content:center;gap:7px;flex-wrap:wrap}.evidence-stream>span{font-family:var(--serif);color:#555}.evidence-stream i{width:30px}
.belief-control{display:grid;grid-template-columns:70px 1fr 70px;gap:10px;align-items:center;margin-top:18px}.belief-control>div{display:flex;flex-direction:column;text-align:center}.belief-control>div span{font-size:22px;font-weight:900}.belief-control>div strong{font-family:var(--serif)}.belief-control label{position:relative}.belief-control label>span{display:block;text-align:center;font-size:8px;font-weight:900;text-transform:uppercase}.belief-control input{width:100%;accent-color:#111}.belief-control label i{position:absolute;bottom:-2px;width:3px;height:16px;background:#111;transform:translateX(-50%);pointer-events:none}.evidence-actions{display:flex;justify-content:center;gap:8px;margin-top:18px}.evidence-actions button,.evidence-result button{border:2px solid #111;border-radius:999px;background:#fffdf8;padding:9px 12px;font-weight:900;cursor:pointer}.evidence-actions button.primary{background:#111;color:#fffdf8}.evidence-actions button:disabled{opacity:.35}.evidence-result{margin-top:16px;background:#fffdf8;border:2px solid #111;border-radius:12px;padding:14px}.evidence-result>strong{font-size:26px}.evidence-result p{font-family:var(--serif)}.belief-history{height:20px;position:relative;border-top:2px solid #111;margin:18px 0 12px}.belief-history i{position:absolute;top:-6px;width:10px;height:10px;border-radius:50%;background:#8157da;transform:translateX(-50%)}

@media(max-width:900px){
  .experimental-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .jar-row{grid-template-columns:1fr 1fr}.evidence-stream{grid-column:1/-1;grid-row:2}.jar-row .jar:last-child{grid-column:2;grid-row:1}
}
@media(max-width:640px){
  .collection-block{padding-bottom:72px}.collection-heading{margin-bottom:20px}.collection-heading h2{font-size:36px}
  .experimental-grid{grid-template-columns:1fr}.compact-tile{min-height:0}
  .ebbinghaus-svg{min-width:0}.ebbinghaus-svg-wrap{margin-top:-5px}
  .spread-lab,.cooperate-lab,.center-lab,.memory-lab,.attention-lab,.evidence-lab,.change-lab{padding:48px 10px 78px}
  .spread-card,.cooperate-card,.cooperate-finale,.center-card,.memory-card,.attention-card,.evidence-card,.change-card{padding:13px 10px;border-width:2px;box-shadow:0 4px 0 #111}
  .spread-head h2,.change-head h2,.memory-head h2,.center-head h2{font-size:36px}
  .spread-controls{grid-template-columns:1fr}.spread-run,.bridge-button{width:100%}.seed-readout{justify-content:space-between}
  .cooperate-card>header{display:block}.score-pair{margin-top:10px}.score-pair span{flex:1}.payoff-note{grid-template-columns:1fr}.round-track{gap:4px}.round-track>div{padding:5px;min-height:78px}.round-track strong,.round-track small{font-size:9px}.cooperate-actions{grid-template-columns:1fr 1fr}.cooperate-actions button{min-height:110px;padding:11px}.cooperate-actions strong{font-size:28px}.opponent-summary{grid-template-columns:1fr}
